import{_ as s}from"./chunks/flaky-detection.CN9mtzEz.js";import{_ as r,C as i,o,c as n,j as t,a as l,E as d,ak as h}from"./chunks/framework.sV-XtlWr.js";const k=JSON.parse('{"title":"Flaky tests & quarantine","description":"How Piwi scores and classifies flaky tests from their history, ranks them by the CI time they waste, and quarantines them with a way out.","frontmatter":{"title":"Flaky tests & quarantine","description":"How Piwi scores and classifies flaky tests from their history, ranks them by the CI time they waste, and quarantines them with a way out.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/flaky-tests.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/flaky-tests.html"}],["meta",{"property":"og:title","content":"Flaky tests & quarantine | Piwi Dashboard"}],["meta",{"property":"og:description","content":"How Piwi scores and classifies flaky tests from their history, ranks them by the CI time they waste, and quarantines them with a way out."}]]},"headers":[],"relativePath":"features/flaky-tests.md","filePath":"features/flaky-tests.md","lastUpdated":1791004553000}'),c={name:"features/flaky-tests.md"};function u(p,e,f,g,m,y){const a=i("Needs");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"flaky-tests-quarantine",tabindex:"-1"},[l("Flaky tests & quarantine "),t("a",{class:"header-anchor",href:"#flaky-tests-quarantine","aria-label":'Permalink to "Flaky tests & quarantine"'},"​")],-1)),d(a,{reporter:""}),e[1]||(e[1]=h('<p>A single run tells you what failed; a few dozen tell you what&#39;s <em>unreliable</em>. This page covers what Piwi computes for one project once it has history: flaky scoring, suspects, regression signals and spec health.</p><p>For the same signals aggregated across every project, see <a href="./analytics.html">Analytics</a>.</p><h2 id="flaky-test-detection" tabindex="-1">Flaky test detection <a class="header-anchor" href="#flaky-test-detection" aria-label="Permalink to &quot;Flaky test detection&quot;">​</a></h2><p>A test is flaky when its result isn&#39;t deterministic. Piwi computes a <strong>flakiness score</strong> (0–100) per test from two signals, weighted 60/40:</p><ul><li><strong>Retry passes</strong> — failed on the first attempt, passed on retry.</li><li><strong>Status alternation</strong> — flips between pass and fail across runs.</li></ul><p>The <strong>failure rate</strong> is shown but not scored.</p><p>The project&#39;s <strong>Failures</strong> tab has a <strong>Flaky</strong> view with a <strong>configurable lookback window</strong> so you can focus on recent behavior or a longer baseline. Each flaky test links to its history and carries a <strong>Quarantine</strong> action.</p><p><strong>Per-environment scoping</strong>: select one environment in the filter bar to score only its runs (the <a href="/guide/reporter.html">reporter</a>&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>).</p><figure><img src="'+s+'" alt="Flaky tests tab listing tests with composite score, failure rate, retry passes, and flip counts"><figcaption>The Flaky view of a project&#39;s Failures tab — each intermittent test scored by retry passes and status flips (failure rate alongside), ranked by impact, filterable by root-cause category, each with its top suspect.</figcaption></figure><h3 id="root-cause-classification" tabindex="-1">Root-cause classification <a class="header-anchor" href="#root-cause-classification" aria-label="Permalink to &quot;Root-cause classification&quot;">​</a></h3><p>Every flaky test is automatically tagged with one of five categories, using keyword and distribution heuristics over its errors, steps, and browser spread, sharpened by the failed requests actually captured and by the <a href="./evidence.html#attempts">attempt diff</a>. It reads the test&#39;s last 100 failed attempts and its last 100 passes from any run, green or red, so the failed attempt of a test that passed on retry counts, and a rare flake keeps its failures however many passes came since:</p><table tabindex="0"><thead><tr><th>Category</th><th>Typical signals</th></tr></thead><tbody><tr><td><code>timing</code></td><td>Timeouts, &quot;to be visible&quot;, <code>waitFor</code>, element-not-found-within</td></tr><tr><td><code>network</code></td><td><code>net::</code> / <code>ERR_</code> errors, 5xx responses, <code>ECONNREFUSED</code>, <code>waitForResponse</code> — plus the count of failed and 5xx requests captured on the failing attempts, and any request that failed on the failing attempt but not the passing one</td></tr><tr><td><code>assertion</code></td><td><code>expect(...)</code>, &quot;Expected:&quot;, snapshot/screenshot comparison — with no timing/network noise</td></tr><tr><td><code>environment</code></td><td>Fails at least 3 times on exactly one browser while another browser passed at least 3 times without failing</td></tr><tr><td><code>other</code></td><td>No clear signal</td></tr></tbody></table><p>A test is classified when it passes on retry in a finished run, and a listed test still without a category when the list opens.</p><p>Filter the flaky table by category to triage a class of failures at once.</p><h3 id="suspects" tabindex="-1">Suspects <a class="header-anchor" href="#suspects" aria-label="Permalink to &quot;Suspects&quot;">​</a></h3><p>A flaky test&#39;s page has a <strong>Flakiness</strong> tab listing its <strong>suspects</strong>: what its failures share and its passes do not, over its last 30 days (at most 200 attempts, from the runs the flaky list reads).</p><table tabindex="0"><thead><tr><th>Factor</th><th>Measured per attempt</th><th>Condition a lab would apply</th></tr></thead><tbody><tr><td>Slow route</td><td>a request&#39;s slowest duration, over the threshold that best separates failures from passes</td><td>delay it to the failures&#39; median</td></tr><tr><td>Failed route</td><td>a request answering 5xx, or with no response</td><td>fail it the same way, or abort it</td></tr><tr><td>Load</td><td>other tests of the same shard running at once, over a threshold</td><td>CPU ×4</td></tr><tr><td>Alongside</td><td>another test overlapping it in time</td><td>run both together</td></tr><tr><td>Before</td><td>the test that ran just before on its worker</td><td>run that test first</td></tr><tr><td>Browser</td><td>its Playwright project</td><td>pin the project</td></tr></tbody></table><p>Each suspect shows its raw counts: <code>GET /api/cart slower (≥1.6 s)</code>, 7 of 8 failures, 3 of 44 passes. It needs 3 failures and a lift of at least 2, <code>(fw + 1)/(f + 2) ÷ (pw + 1)/(p + 2)</code>; at most 5 are listed, ranked by lift × those failures. A neighbor names the paths both tests write, marked approximate when the overlap crosses shards, whose clocks agree only roughly. First attempts, the UTC hour and other runs on the same environment are context, without a condition. Nothing is stored.</p><p>The flaky list names each test&#39;s top suspect, the <a href="./evidence.html#attempts">Attempts</a> tab links a request to its suspect, the clue <code>known-flake-suspect</code> marks a failure showing one, and MCP&#39;s <code>get_flake_profile</code> returns the profile. The <a href="./flake-lab.html">Flake Lab</a> tests each suspect against a control run.</p><h3 id="verified-fixed" tabindex="-1">Verified fixed <a class="header-anchor" href="#verified-fixed" aria-label="Permalink to &quot;Verified fixed&quot;">​</a></h3><p>When a <a href="./flake-lab.html#verify-a-fix"><code>piwi flake verify</code></a> experiment holds, the test reads <strong>verified fixed on <code>&lt;commit&gt;</code></strong> on its Flakiness tab and leaves the ranking, and with it the MCP <code>list_flaky_tests</code> tool, quarantine candidates and the analytics leaderboard. The Flaky view lists it apart, under <strong>Verified fixed</strong>. The first retry-pass in a run that started after the verification brings it back. A <code>still-fails</code> verify, or a later reproduction, removes the mark; an <code>inconclusive</code> one changes nothing.</p><h3 id="impact-ranking" tabindex="-1">Impact ranking <a class="header-anchor" href="#impact-ranking" aria-label="Permalink to &quot;Impact ranking&quot;">​</a></h3><p>Piwi ranks flaky tests by <strong>impact</strong> — derived from wasted CI minutes (retries × average failed duration) and pipeline-block effect — so you fix the ones that hurt most first. A color-coded dot makes it scannable:</p><ul><li>🟢 green — under 5 wasted minutes</li><li>🟡 amber — under 30 minutes</li><li>🔴 red — 30 minutes or more</li></ul><h3 id="per-test-stability-trend" tabindex="-1">Per-test stability trend <a class="header-anchor" href="#per-test-stability-trend" aria-label="Permalink to &quot;Per-test stability trend&quot;">​</a></h3><p>The <strong>Trend</strong> tab of a test&#39;s page draws its pass rate, flaky rate and average duration over the last 30, 90 or 365 days, one point per UTC day, week or month, with the project&#39;s timeline markers, so you can see whether a fix actually stuck. The same series is the MCP <code>get_test_stability_trend</code> tool.</p><h2 id="quarantine-with-a-way-out" tabindex="-1">Quarantine, with a way out <a class="header-anchor" href="#quarantine-with-a-way-out" aria-label="Permalink to &quot;Quarantine, with a way out&quot;">​</a></h2><p>Detecting a flaky test doesn&#39;t stop it blocking merges. Quarantine does — without hiding it.</p><p>The usual approach is <code>--grep-invert @quarantine</code>: the test stops running, nothing ever proves it&#39;s fixed, and the list only grows.</p><p><strong>A quarantined test in Piwi keeps running and keeps reporting.</strong> It is excluded from the <a href="/guide/ci.html#blocking-a-merge">CI gate</a>&#39;s <code>--max-failed</code>, <code>--max-new-regressions</code>, <code>--max-new-flaky</code>, <code>--require-tag</code> and <code>--require-selection</code> checks and the <a href="./pr-feedback.html#what-gets-posted">commit status</a>, nothing else. That makes the exit possible:</p><ul><li>Passing executions after quarantine (one per attempt per browser project) accumulate as a <strong>streak</strong>; one failure resets it.</li><li>After five consecutive passes the test is flagged <strong>ready to release</strong> — the dashboard tells you, rather than waiting to be asked.</li><li>A fix <a href="#verified-fixed">verified</a> after the quarantine flags it at once, while it holds. Release stays yours to click.</li><li><strong>Candidates</strong> (API only) are flaky tests wasting 2+ CI minutes with a score of 40+, ranked by impact. A test that flakes constantly but finishes in 200 ms costs nothing; one that flakes weekly and burns a four-minute timeout is what actually hurts.</li><li><strong>Debt</strong> is reported in aggregate: how many are quarantined, how many are ready to release, how long the oldest has been in, and how many still have no passing streak at all.</li></ul><p>The gate always states how many failures quarantine excluded — a green gate that silently ignored failures would be worthless — and <code>--max-quarantined</code> sets a ceiling so the list can&#39;t grow unbounded.</p><p>Manage it from the <strong>Quarantine</strong> view of the project&#39;s <strong>Failures</strong> tab, or over the REST API (see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>).</p><h2 id="regression-signals" tabindex="-1">Regression signals <a class="header-anchor" href="#regression-signals" aria-label="Permalink to &quot;Regression signals&quot;">​</a></h2><p>Individual test cases in a run carry at-a-glance badges:</p><ul><li><strong>New regression</strong> (red) — failing here but passing in the baseline (the last passing run)</li><li><strong>Newly flaky</strong> (purple) — the first run in which the test was flaky</li><li><strong>Passed on retry</strong> (purple) — failed at least once in this run, then passed</li></ul><p>Filters on the run&#39;s test-case list show only new regressions or new flaky tests.</p><p>A failing execution shows the same badges in its header (see <a href="./evidence.html#one-execution-diagnosis-first">Test case detail</a>).</p><h2 id="spec-health-by-file" tabindex="-1">Spec health by file <a class="header-anchor" href="#spec-health-by-file" aria-label="Permalink to &quot;Spec health by file&quot;">​</a></h2><p>The project&#39;s <strong>Tests</strong> tab has a <strong>Group by File</strong> view that groups tests by their first two path segments (<code>tests/admin</code> for <code>tests/admin/users.spec.ts</code>) and carries that group&#39;s pass rate, flaky rate, failure count, execution count and average time over the last 90 days in its header, so an unhealthy area of the suite jumps out.</p><h2 id="across-every-project" tabindex="-1">Across every project <a class="header-anchor" href="#across-every-project" aria-label="Permalink to &quot;Across every project&quot;">​</a></h2><p>Everything above is scoped to one project. The <strong>Analytics</strong> page lifts the same signals to your whole portfolio over a time window you choose — portfolio health, a pass-rate heatmap, wasted CI minutes, regression velocity, a global flaky leaderboard, and an auto-generated insights feed. See <a href="./analytics.html">Analytics</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/regression-or-flaky.html">Regression or flake?</a>: is one red test flaky?</li><li><a href="/recipes/flaky-cleanup.html">Cut costly flakiness</a>: fix the costliest flaky tests first</li><li><a href="./run-changes.html">What changed in a run</a> — the Changes tab: new failures, fixed tests, commits since a baseline</li><li><a href="./slow-tests.html">Slow tests &amp; wasted time</a> — duration trends, slowest tests, and timeout opportunities</li><li><a href="./analytics.html">Analytics</a> — the same signals across every project</li><li><a href="./ui-overview.html">UI overview</a> — where each of these views lives in the dashboard</li><li><a href="/guide/reporter.html">Reporter</a> — how retries, traces, and run metadata get captured</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a> — the test-side setup behind network analysis and Web Vitals</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a>: the failures grouped by cause</li></ul>',44))])}const v=r(c,[["render",u]]);export{k as __pageData,v as default};
